import { z } from 'zod';

/** Core analytics events from the product design. Payload shapes per type are added in contracts v0.2. */
export const EVENT_TYPES = [
  'app_open',
  'onboarding_complete',
  'persona_selected',
  'decision_made',
  'rewind_used',
  'event_triggered',
  'minigame_complete',
  'quiz_submitted',
  'module_complete',
  'badge_earned',
  'language_changed',
  'sync_complete',
] as const;
export const EventType = z.enum(EVENT_TYPES);
export type EventType = z.infer<typeof EventType>;

/**
 * One queued event. `eventId` is generated by the client, so the server can
 * ignore duplicates when a flaky connection retries a batch.
 */
export const SyncEvent = z.strictObject({
  eventId: z.uuid(),
  profileId: z.uuid(),
  type: EventType,
  occurredAt: z.iso.datetime(),
  /** Per-profile counter, so the server can order events from one device. */
  seq: z.int().nonnegative(),
  payload: z.record(z.string(), z.unknown()),
});
export type SyncEvent = z.infer<typeof SyncEvent>;

export const SyncBatch = z.strictObject({
  events: z.array(SyncEvent).min(1).max(500),
});
export type SyncBatch = z.infer<typeof SyncBatch>;
